stuff_ageGenes <- data.frame(revigo.data_ageGenes);
names(stuff_ageGenes) <- revigo.names;

stuff_ageGenes$value <- as.numeric( as.character(stuff_ageGenes$value) );
stuff_ageGenes$frequency <- as.numeric( as.character(stuff_ageGenes$frequency) );
stuff_ageGenes$uniqueness <- as.numeric( as.character(stuff_ageGenes$uniqueness) );
stuff_ageGenes$dispensability <- as.numeric( as.character(stuff_ageGenes$dispensability) );

# by default, outputs to a PDF file
pdf( file="revigo_treemap_ageGenes.pdf", width=16, height=9 ) # width and height are in inches
# check the tmPlot command documentation for all possible parameters - there are a lot more
treemap(stuff_ageGenes,
	index = c("representative","description"),
	vSize = "value",
	type = "categorical",
#	algorithm = "pivotSize",
#	type = "dens",
	fontsize.labels = c(0,10),
	fontsize.legend = 10,
	vColor = "representative",
	palette = colorRampPalette(c("red4", "indianred", "gray73"))(40),
	title = "Map of Enriched GO Biological Processes: Age-related Genes",
	title.legend = "Parent Nodes",	
	inflate.labels = FALSE,      # set this to TRUE for space-filling group labels - good for posters
	lowerbound.cex.labels = .1,   # try to draw as many labels as possible (still, some small squares may not get a label)
	bg.labels = "#CCCCCCAA",   # define background color of group labels # "#CCCCCC00" is fully transparent, "#CCCCCCAA" is semi-transparent grey, NA is opaque
	position.legend = "right"
)
dev.off()

reorder(cc.df$origin, cc.df$count)

